// Filter + normalize UAZAPI payload
const body = $input.first().json.body || $input.first().json;

// Only process "messages" events
const eventType = body.EventType || '';
if (eventType !== 'messages') return [];

// Get message data (UAZAPI format)
const msg = body.message || body.data || {};

// Ignore own messages
if (msg.fromMe === true) return [];

// Ignore groups
if (msg.isGroup === true) return [];

// Ignore empty messages
const text = msg.text || msg.content?.text || msg.body || '';
const msgType = (msg.type || msg.mediaType || 'text').toLowerCase();
const hasMedia = ['image', 'audio', 'video', 'document', 'sticker', 'ptt'].includes(msgType);

if (!text && !hasMedia) return [];

// Normalize and pass through with data in expected format
const chatid = msg.chatid || (msg.key && msg.key.remoteJid) || '';

return [{
  json: {
    ...($input.first().json),
    body: {
      ...body,
      data: {
        ...msg,
        key: { 
          id: msg.messageid || msg.id || '', 
          remoteJid: chatid,
          fromMe: false 
        },
        pushName: msg.senderName || body.chat?.name || 'Cliente',
        message: { conversation: text },
        messageType: msg.messageType || (hasMedia ? msgType + 'Message' : 'conversation'),
        text: text,
        body: text,
        chatid: chatid,
        messageid: msg.messageid || msg.id || ''
      }
    }
  }
}];

const rawOutput = $input.first().json.output || $input.first().json.response || '';
const userMessage = String($('Get Message').item.json.message || '');
let contextText = '';
try { contextText = String($('Context Refiner').item.json.text || ''); } catch(e) {}
let profileName = 'Cliente';
try { profileName = String($('Global Variables').item.json.profile_name || 'Cliente'); } catch(e) {}

let parsed;
try {
  const cleaned = String(rawOutput).replace(/```json\n?|\n?```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    type: 'response',
    message_blocks: [String(rawOutput || 'Deixa eu verificar isso pra você ✨')],
    delay_seconds: 1
  };
}

if (!parsed || typeof parsed !== 'object') {
  parsed = { type: 'response', message_blocks: ['Deixa eu verificar isso pra você ✨'], delay_seconds: 1 };
}

if (!parsed.type) parsed.type = 'response';
if (!parsed.message_blocks && parsed.response) parsed.message_blocks = [parsed.response];
if (!parsed.message_blocks) parsed.message_blocks = ['Deixa eu verificar isso pra você ✨'];
if (!parsed.delay_seconds) parsed.delay_seconds = 1;

function words(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean);
}

function responseAsk(message, reason, blockedAction) {
  return [{
    json: {
      type: 'response',
      message_blocks: [message],
      delay_seconds: 1,
      blocked_action: blockedAction || parsed.action || null,
      block_reason: reason || 'missing_required_booking_data'
    }
  }];
}

function hasTimezone(value) {
  return /(?:Z|[+-]\d{2}:?\d{2})$/i.test(String(value || '').trim());
}

function normalizeIso(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return hasTimezone(raw) ? raw : `${raw}-03:00`;
}

function isValidDate(value) {
  const t = Date.parse(value);
  return Number.isFinite(t);
}

function plusMinutes(value, minutes) {
  const d = new Date(value);
  d.setMinutes(d.getMinutes() + minutes);
  const pad = n => String(n).padStart(2, '0');
  const yyyy = d.getFullYear();
  const mm = pad(d.getMonth() + 1);
  const dd = pad(d.getDate());
  const hh = pad(d.getHours());
  const mi = pad(d.getMinutes());
  return `${yyyy}-${mm}-${dd}T${hh}:${mi}:00-03:00`;
}

function extractHour(text) {
  const s = String(text || '').toLowerCase();
  const m = s.match(/\b(?:às\s*)?(\d{1,2})(?::|h)?(\d{2})?\s*(?:h|hr|hrs|hora|horas)?\b/);
  if (!m) return null;
  const hour = Number(m[1]);
  const minute = m[2] ? Number(m[2]) : 0;
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

function extractDate(args) {
  if (args && /^\d{4}-\d{2}-\d{2}$/.test(String(args.date || ''))) return String(args.date);
  const iso = contextText.match(/\b(20\d{2}-\d{2}-\d{2})\b/);
  if (iso) return iso[1];
  const br = contextText.match(/\b(\d{2})\/(\d{2})(?:\/(20\d{2}))?\b/);
  if (br) {
    const year = br[3] || String(new Date().getFullYear());
    return `${year}-${br[2]}-${br[1]}`;
  }
  return '';
}

function isTimeSelection(text) {
  const time = extractHour(text);
  if (!time) return false;
  const s = String(text || '').toLowerCase();
  const hasSchedulingContext = /hor[aá]rios?|agenda|dispon[ií]ve|qual desses|visita|agend/i.test(contextText + ' ' + rawOutput);
  const asksNewDate = /amanh[aã]|hoje|segunda|terça|ter[cç]a|quarta|quinta|sexta|s[aá]bado|domingo|\d{1,2}\/\d{1,2}/i.test(s);
  return hasSchedulingContext && !asksNewDate;
}

if (parsed.type === 'action') {
  parsed.action_args = parsed.arguments || parsed.action_args || {};
  if (!parsed.pre_message_blocks) parsed.pre_message_blocks = ['Aguarde um momento ✨'];
  if (!parsed.pre_delay_seconds) parsed.pre_delay_seconds = 2;

  // Deterministic guard: when the client chooses one of the offered times, never check availability again.
  // Move to booking confirmation path and let required-data validation ask only what is missing.
  if (parsed.action === 'check_availability' && isTimeSelection(userMessage)) {
    const chosenTime = extractHour(userMessage);
    const chosenDate = extractDate(parsed.action_args);
    if (chosenDate && chosenTime) {
      parsed.action = 'create_booking';
      parsed.action_args = {
        ...parsed.action_args,
        type: parsed.action_args.type || 'VISITA_PRESENCIAL',
        starts_at: `${chosenDate}T${chosenTime}:00-03:00`,
        ends_at: plusMinutes(`${chosenDate}T${chosenTime}:00-03:00`, 45),
        customer_name: parsed.action_args.customer_name || profileName,
        visit_reason: parsed.action_args.visit_reason || parsed.action_args.notes || 'Atendimento na ORIN Joias',
        notes: parsed.action_args.notes || `Horário escolhido pelo cliente no WhatsApp: ${chosenDate} ${chosenTime}`
      };
      parsed.pre_message_blocks = ['Perfeito, vou separar esse horário ✨'];
      parsed.pre_delay_seconds = 1;
    } else {
      return responseAsk('Perfeito. Só me confirma o dia desse horário, por favor?', 'missing_booking_date_after_time_selection', 'create_booking');
    }
  }

  if (parsed.action === 'check_availability') {
    const args = parsed.action_args;
    if (!String(args.date || '').trim()) {
      return responseAsk('Qual dia fica bom pra você?', 'missing_availability_date');
    }
    args.date = String(args.date).trim();
    if (args.period) args.period = String(args.period).trim().toLowerCase();
  }

  if (parsed.action === 'create_booking') {
    const args = parsed.action_args;
    args.starts_at = normalizeIso(args.starts_at);
    args.ends_at = normalizeIso(args.ends_at);

    if (args.starts_at && !isValidDate(args.starts_at)) {
      return responseAsk('Me confirma o dia e horário certinho pra eu registrar aqui ✨', 'invalid_booking_start');
    }
    if (args.starts_at && !args.ends_at) {
      args.ends_at = plusMinutes(args.starts_at, 45);
    }
    if (args.ends_at && !isValidDate(args.ends_at)) {
      return responseAsk('Me confirma o horário final certinho pra eu registrar aqui ✨', 'invalid_booking_end');
    }

    const hasStart = Boolean(args.starts_at);
    const hasEnd = Boolean(args.ends_at);
    const hasFullName = words(args.customer_name).length >= 2 && !/^cliente$/i.test(String(args.customer_name || '').trim());
    const hasReason = Boolean(String(args.visit_reason || '').trim()) || Boolean(String(args.notes || '').trim());

    if (!hasFullName) return responseAsk('Antes de confirmar, me passa seu nome completo, por favor? ✨', 'missing_customer_full_name', 'create_booking');
    if (!hasReason) return responseAsk('E qual seria o motivo da visita ou a peça que você quer ver?', 'missing_visit_reason', 'create_booking');
    if (!hasStart || !hasEnd) return responseAsk('Me confirma o dia e horário certinho pra eu registrar aqui ✨', 'missing_booking_datetime', 'create_booking');

    const detailParts = [];
    detailParts.push(`Cliente: ${args.customer_name}`);
    detailParts.push(`Motivo da visita: ${args.visit_reason || args.notes}`);
    if (args.notes && args.notes !== args.visit_reason) detailParts.push(`Observações: ${args.notes}`);
    parsed.action_args.notes = detailParts.join('\n');
  }
}

return [{ json: parsed }];

const actionType = $('Code: Parse Agent Output').item.json.action;
const toolResult = $input.first().json;
const userMessage = $('Get Message').item.json.message;
const chatHistory = $('Context Refiner').item.json.text || '';

let toolContext = '';
if (actionType === 'check_availability') {
  const slots = Array.isArray(toolResult.slots) ? toolResult.slots : [];
  const date = toolResult.date || '';
  const dayName = toolResult.day_name || '';
  const message = toolResult.message || '';
  toolContext = `Resultado da agenda CRM:\n${JSON.stringify({date, dayName, slots, message}, null, 2)}\n\nEscreva como Lara. Mostre apenas estes horários. Não invente outro horário. Não envie endereço. Não use frase robótica repetida.`;
} else if (actionType === 'create_booking') {
  const hasData = toolResult.id || toolResult.success || toolResult.accepted || toolResult.appointment_id;
  const success = !toolResult.error && hasData;
  if (success) {
    toolContext = `Agendamento criado com sucesso no CRM:\n${JSON.stringify(toolResult, null, 2)}\n\nConfirme para o cliente de forma humana. Inclua data, hora, endereço, estacionamento e Google Maps.`;
  } else {
    toolContext = `Falha ao criar agendamento no CRM:\n${JSON.stringify(toolResult, null, 2)}\n\nResponda com calma, peça para confirmar só o dado necessário ou diga que vai chamar a equipe.`;
  }
}

return [{ json: { user_message: userMessage, chat_history: chatHistory, tool_context: toolContext, action_type: actionType } }];

const rawText = $input.first().json.text || $input.first().json.output || '';
let parsed;

try {
  const cleaned = rawText.replace(/```json\n?|\n?```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    type: 'post_action_response',
    message_blocks: [rawText || 'Pronto, já verifiquei pra você ✨'],
    delay_seconds: 2
  };
}

// Normalize to message_blocks format
if (!parsed.message_blocks && parsed.response) {
  parsed.message_blocks = [parsed.response];
}
if (!parsed.message_blocks) parsed.message_blocks = ['Pronto! ✨'];
if (!parsed.delay_seconds) parsed.delay_seconds = 2;
if (!parsed.type) parsed.type = 'post_action_response';

// response for backward compat (Code: Detectar Handoff reads it)
parsed.response = parsed.message_blocks.join('\n');
parsed.is_handoff = false;
parsed.handoff_reason = '';

return [{ json: parsed }];

const data = Object.assign({}, $json);
