    else if (pc==='corrigir') { config.corrections.push(pa); responseText=`✅ Correção salva (${config.corrections.length} total):\n"${pa}"`; }
    else if (pc==='persona')  { config.persona_extra=pa; responseText=`✅ Personalidade atualizada:\n"${pa}"`; }
    else if (pc==='objetivo') { config.objetivos.push(pa); responseText=`✅ Objetivo salvo (${config.objetivos.length} total):\n"${pa}"`; }
    else if (pc==='tom')      { config.tom=parseInt(pa,10); responseText=`✅ Tom atualizado:\n${tomBar(config.tom)}`; }
    else if (pc==='escrita')   { config.write_rules.push(pa); responseText=`✅ Regra de escrita salva (${config.write_rules.length} total):\n"${pa}"`; }
    else if (pc==='newprompt') { config.custom_prompt=pa; responseText=`✅ Novo prompt salvo (${pa.length} chars).`; }
    else if (pc==='link') {
      const p=pa.split('|').map(x=>x.trim());
      config.links.push({name:p[0], url:p[1], description:p[2] || ''});
      responseText=`✅ Link salvo (${config.links.length} total):\n${p[0]} — ${p[1]}`;
    }
    else if (pc==='exemplo')  {
      const m=pa.match(/entrada:(.+)\|saida:(.+)/i);
      if(m){ config.examples.push({input:m[1].trim(),output:m[2].trim()}); responseText=`✅ Exemplo salvo (${config.examples.length} total).`; }
    }
    save = true;
  } else {
    responseText = 'ℹ️ Nada pendente.';
  }

} else if (command === 'cancelar') {
  if (config._pending) { delete config._pending; save=true; responseText='↩️ Cancelado.'; }
  else { responseText='ℹ️ Nada pendente.'; }

} else if (command === 'modo_livre') {
  if (!args) {
    sessionAction = 'activate';
    responseText = `🟢 Modo livre — fale o que quer ajustar na LARA e aplico automaticamente.`;
  } else {
    modo_livre = true;
  }
}

// Serialize config to plain object to avoid n8n Proxy issues
let configOut;
try {
  const keys = ['rules','write_rules','corrections','examples','links','objetivos','persona_extra','tom',
    'custom_prompt','tempo_resposta','idioma','personalizacao','transparencia','feedback',
    'erros_desculpas','escalacao','saudacoes','tonalidade_sit','uso_exemplos','empatia',
    'chamada_acao','fechamento','conhecimento','criatividade','humor','analise_sentimento',
    'seguranca','_pending'];
  configOut = {};
  for (const k of keys) {
    if (config[k] !== undefined) configOut[k] = config[k];
  }
} catch(e) { configOut = config; }
return [{ json: { config: configOut, responseText, save, sessionAction, modo_livre, command } }];

const contextText = $('Context Refiner').item.json.text || '';
const rawConfig = $input.first().json.propertyName || null;

let config;
try {
  config = rawConfig ? JSON.parse(rawConfig) : null;
} catch(e) { config = null; }

const scalarFields = [
  ['tempo_resposta', 'Tempo de resposta'],
  ['idioma', 'Idioma/regionalismo'],
  ['escalacao', 'Escalação'],
  ['saudacoes', 'Saudações/despedidas'],
  ['erros_desculpas', 'Erros e desculpas'],
  ['empatia', 'Empatia'],
  ['humor', 'Humor'],
  ['criatividade', 'Criatividade'],
  ['chamada_acao', 'Chamada para ação'],
  ['fechamento', 'Fechamento'],
  ['seguranca', 'Segurança'],
  ['personalizacao', 'Personalização'],
  ['transparencia', 'Transparência'],
  ['feedback', 'Feedback'],
  ['tonalidade_sit', 'Tonalidade por situação'],
  ['uso_exemplos', 'Uso de exemplos'],
  ['analise_sentimento', 'Análise de sentimento'],
  ['conhecimento', 'Conhecimento'],
];

const hasScalar = !!config && scalarFields.some(([key]) => {
  const val = config[key];
  return val !== undefined && val !== null && String(val).trim() !== '';
});

const isEmpty = !config || (
  !config.custom_prompt &&
  !config.rules?.length &&
  !config.write_rules?.length &&
  !config.links?.length &&
  !config.corrections?.length &&
  !config.persona_extra &&
  !config.examples?.length &&
  !config.objetivos?.length &&
  (config.tom === undefined || config.tom === null || config.tom === 7) &&
  !hasScalar
);

let rootSection = '\n\n---\nROOT_CONFIG — FONTE DE VERDADE DA LARA:';
rootSection += '\nEstas instruções vêm do ROOT administrativo e têm prioridade sobre qualquer padrão de comportamento.';
rootSection += '\nSe houver conflito, siga sempre o ROOT_CONFIG.';

if (isEmpty) {
  rootSection += '\n\nStatus: ROOT_CONFIG vazio. Use comportamento neutro, seguro e consultivo.';
  return [{ json: { text: contextText + rootSection } }];
}

if (config.custom_prompt) {
  rootSection += `\n\nPrompt customizado principal:\n${config.custom_prompt}`;
}

if (config.persona_extra) {
  rootSection += `\n\nPersonalidade e estilo:\n${config.persona_extra}`;
}

if (config.objetivos && config.objetivos.length > 0) {
  rootSection += '\n\nObjetivos ativos:';
  config.objetivos.forEach(o => { rootSection += `\n- ${o}`; });
}

if (config.tom !== undefined && config.tom !== null) {
  const tom = Number(config.tom);
  const desc = tom <= 2 ? 'muito formal e profissional, linguagem sofisticada'
             : tom <= 4 ? 'formal e profissional'
             : tom <= 6 ? 'neutro, equilibrado entre formal e informal'
             : tom <= 8 ? 'amigável, próxima e calorosa'
             : 'muito descontraída, leve e próxima';
  rootSection += `\n\nTom de voz (${tom}/10): ${desc}.`;
}

if (config.rules && config.rules.length > 0) {
  rootSection += '\n\nRegras de comportamento:';
  config.rules.forEach(r => { rootSection += `\n- ${r}`; });
}

if (config.write_rules && config.write_rules.length > 0) {
  rootSection += '\n\nRegras de escrita:';
  config.write_rules.forEach(r => { rootSection += `\n- ${r}`; });
}

if (config.links && config.links.length > 0) {
  rootSection += '\n\nLinks úteis disponíveis:';
  config.links.forEach(link => {
    const desc = link.description ? ` — ${link.description}` : '';
    rootSection += `\n- ${link.name}: ${link.url}${desc}`;
  });
  rootSection += '\nUse estes links quando o cliente pedir ou quando forem úteis para responder diretamente à solicitação.';
}

if (config.corrections && config.corrections.length > 0) {
  rootSection += '\n\nCorreções administrativas:';
  config.corrections.forEach(c => { rootSection += `\n- ${c}`; });
}

if (config.examples && config.examples.length > 0) {
  rootSection += '\n\nExemplos de comportamento desejado:';
  config.examples.forEach(ex => {
    rootSection += `\nEntrada: "${ex.input}" → Saída: "${ex.output}"`;
  });
}

const scalarLines = scalarFields
  .map(([key, label]) => [label, config[key]])
  .filter(([, val]) => val !== undefined && val !== null && String(val).trim() !== '');

if (scalarLines.length > 0) {
  rootSection += '\n\nParâmetros adicionais do ROOT:';
  scalarLines.forEach(([label, val]) => { rootSection += `\n- ${label}: ${val}`; });
}

rootSection += `

AJUSTES OPERACIONAIS APLICADOS SOBRE O ROOT_CONFIG:
- Exemplos com dias, datas ou horários são sempre ilustrativos. Nunca copie datas ou horários literais de exemplos.
- Para disponibilidade de agenda, use exclusivamente horários retornados pelo CRM.
- Quando apresentar horários disponíveis, envie somente as opções retornadas pelo CRM no mesmo bloco, sem endereço e sem estacionamento.
- Depois que o cliente escolher um horário, colete nome completo e motivo da visita se ainda faltarem.
- Só use create_booking quando houver horário escolhido, nome completo e motivo da visita.
- Não use termos como "pré-confirmado" antes do retorno bem-sucedido do CRM.
- Após create_booking bem-sucedido, confirme o agendamento e envie data, horário, endereço completo, ponto de referência e estacionamento no mesmo bloco.
- Links oficiais devem ser usados somente quando estiverem no ROOT_CONFIG, em Links úteis, Conhecimento ou Prompt customizado.
`;

return [{ json: { text: contextText + rootSection } }];

