const rawText   = $input.first().json.text || '';
const configRaw = $('ROOT: Ler Config Redis').item.json.propertyName || '{}';

let llmData;
try {
  const cleaned   = rawText.replace(/```json\n?|\n?```/g,'').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  llmData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(cleaned);
} catch(e) {
  llmData = { actions:[{type:'none'}], response:'⚠️ Não entendi. Seja mais direto. Ex: "seja mais calorosa".' };
}

let config;
try { config = JSON.parse(configRaw); } catch(e) { config={}; }
config.rules         = config.rules         || [];
config.corrections   = config.corrections   || [];
config.examples      = config.examples      || [];
config.objetivos     = config.objetivos     || [];
config.persona_extra = config.persona_extra || '';
config.links         = config.links         || [];
config.tom           = config.tom !== undefined ? Number(config.tom) : 7;

const actions = llmData.actions || (llmData.action ? [{type:llmData.action,value:llmData.value,example_input:llmData.example_input,example_output:llmData.example_output}] : []);

let needsSave = false;
const applied = [];

for (const act of actions) {
  const type  = act.type  || '';
  const value = (act.value||'').trim();
  if      (type==='rule'       && value) { config.rules.push(value);             applied.push(`📋 Regra: "${value}"`);          needsSave=true; }
  else if (type==='correction' && value) { config.corrections.push(value);       applied.push(`🔧 Correção: "${value}"`);        needsSave=true; }
  else if (type==='persona'    && value) { config.persona_extra=value;            applied.push(`🎭 Personalidade: "${value}"`);   needsSave=true; }
  else if (type==='objetivo'   && value) { config.objetivos.push(value);          applied.push(`🎯 Objetivo: "${value}"`);        needsSave=true; }
  else if (type==='example'    && act.example_input) {
    config.examples.push({input:act.example_input,output:act.example_output||''});
    applied.push(`💡 "${act.example_input}" → "${act.example_output}"`);
    needsSave=true;
  } else if (type==='link' && value) {
    const p=value.split('|').map(x=>x.trim());
    if (p[0] && p[1]) {
      config.links.push({name:p[0], url:p[1], description:p[2]||''});
      applied.push(`🔗 Link: ${p[0]} — ${p[1]}`);
      needsSave=true;
    }
  } else if (type==='tom' && value) {
    const v=parseInt(value,10);
    if(!isNaN(v)&&v>=0&&v<=10) { config.tom=v; applied.push(`🎚️ Tom: ${v}/10`); needsSave=true; }
  }
}

if (needsSave) config.updated_at = new Date().toISOString();

const responseText = applied.length>0
  ? `✅ ${applied.length} alteração(ões) aplicada(s):\n`+applied.join('\n')
  : llmData.response || '⚠️ Não entendi. Seja mais específico.';

return [{ json: { config, responseText, needs_save: needsSave } }];
